#!/usr/bin/env python3
"""Patch: passive auto-cycle through all 9 videos."""

import base64, os, subprocess

ROOT = os.path.expanduser("~/insight-dashboards")

HTML_B64 = ""

dest = os.path.join(ROOT, "frontend/youtube-shorts/index.html")
with open(dest, "wb") as f:
    f.write(base64.b64decode(HTML_B64))
print("  wrote frontend/youtube-shorts/index.html")

subprocess.run(["git", "-C", ROOT, "add", "-A"], check=True)
r = subprocess.run(["git", "-C", ROOT, "commit", "-m", "feat: passive auto-cycle all 9 videos on ENDED"], check=False)
if r.returncode not in (0, 1):
    raise SystemExit(f"git commit failed: {r.returncode}")
subprocess.run(["git", "-C", ROOT, "push", "origin", "HEAD"], check=True)
print("Done.")
